export function ListDivider({
  label = "{{label}}",
  style = "{{style}}",
  accent = "{{accent}}",
  showSecondLabel = {{showSecondLabel}},
  spacing = {{spacing}},
}) {
  const gap = style === "spaced" ? spacing * 2 : spacing;
  const Divider = ({ text }) => (
    <li role="separator" aria-orientation="horizontal" style={{ display: "flex", alignItems: "center", margin: `${gap}px 0`, color: accent, fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em" }}>
      <span style={{ flex: 1, height: 1, background: accent, opacity: 0.35 }} />
      {style !== "line" && <span style={{ padding: "0 8px" }}>{text}</span>}
      <span style={{ flex: 1, height: 1, background: accent, opacity: 0.35 }} />
    </li>
  );
  const itemStyle = { padding: "8px 4px" };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 300, width: 300, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        <li style={itemStyle}>Stand-up notes</li>
        <li style={itemStyle}>Design review</li>
        <Divider text={label} />
        <li style={itemStyle}>Sprint planning</li>
        <li style={itemStyle}>Retro summary</li>
        {showSecondLabel && (
          <>
            <Divider text="Last week" />
            <li style={itemStyle}>Kickoff notes</li>
          </>
        )}
      </ul>
    </div>
  );
}
